const r = await api.get('/customers', {});
if (!Array.isArray(r.items)) {return 'Unexpected format';}
let max = -Infinity;
let maxId = null;
for (const c of r.items) {
  if (c.points > max) {max = c.points; maxId = c.id;}
}
return {maxId, maxPoints: max};

